import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { mkdtemp, readFile, rm, mkdir, writeFile } from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
const profile = await mkdtemp(path.join(os.tmpdir(), 'legendgirl-som-chrome-'));
const chrome = spawn('/Applications/Google Chrome.app/Contents/MacOS/Google Chrome', ['--headless=new', '--mute-audio', '--no-first-run', '--no-default-browser-check', '--autoplay-policy=no-user-gesture-required', '--remote-debugging-port=0', '--user-data-dir='+profile, 'about:blank'], {stdio:'ignore'});
let ws;
try {
 let port;
 for(let i=0;i<100;i++) { try { port=(await readFile(path.join(profile,'DevToolsActivePort'),'utf8')).split('\n')[0];break; } catch {} await new Promise(r=>setTimeout(r,100)); }
 assert.ok(port,'Chrome de QA inicializado');
 const tabs=await (await fetch('http://127.0.0.1:'+port+'/json/list')).json();
 ws=new WebSocket(tabs.find(t=>t.type==='page').webSocketDebuggerUrl);
 await new Promise(r=>ws.onopen=r);
 let id=0;const pending=new Map();ws.onmessage=e=>{const d=JSON.parse(e.data);if(d.id){pending.get(d.id)?.(d);pending.delete(d.id);}};
 const call=(method,params={})=>new Promise(resolve=>{const n=++id;pending.set(n,resolve);ws.send(JSON.stringify({id:n,method,params}));});
 const evaluate=async expression=>{const r=await call('Runtime.evaluate',{expression,awaitPromise:true,returnByValue:true});if(r.result?.exceptionDetails)throw Error(JSON.stringify(r.result.exceptionDetails));return r.result?.result?.value;};
 await call('Emulation.setDeviceMetricsOverride',{width:1280,height:800,deviceScaleFactor:1,mobile:false});
 await call('Page.navigate',{url:'http://127.0.0.1:3000'});await new Promise(r=>setTimeout(r,300));
 const output='docs/diario-ia/qa-resultados/carregamento-fuga';await mkdir(output,{recursive:true});
 const save=async name=>{const shot=await call('Page.captureScreenshot',{format:'png'}),bytes=Buffer.from(shot.result.data,'base64');await writeFile(output+'/'+name+'.png',bytes);await writeFile('/tmp/legendgirl-fuga-'+name+'.png',bytes);};
 const held=await evaluate(`(async()=>{
  const {BearChasePhase}=await import('/src/js/bear-chase/BearChasePhase.js');
  const {ChaseRenderer3D}=await import('/src/js/bear-chase/ChaseRenderer3D.js');
  window.ChaseRenderer3D=ChaseRenderer3D;window.BearChasePhase=BearChasePhase;
  const canvas=document.createElement('canvas');canvas.width=1280;canvas.height=800;document.body.replaceChildren(canvas);document.body.style='margin:0';canvas.style='width:100vw;height:100vh';
  window.canvas=canvas;window.silent={isMuted:()=>true,getMasterVolume:()=>0};
  const original=Image.prototype.decode;let release;const gate=new Promise(r=>release=r);window.releaseAsset=release;
  Image.prototype.decode=async function(){if(this.src.includes('urso-atlas-v2'))await gate;return original.call(this);};window.originalDecode=original;
  window.phase=new BearChasePhase({canvas,audio:silent,enabled:()=>true,campaign:true});window.startPromise=phase.start();
  for(let i=0;i<200&&!phase.introReady;i++)await new Promise(r=>setTimeout(r,30));
  if(!phase.introReady||phase.ready)throw Error('Abertura deve estar pronta antes do atlas 3D');
  for(let i=0;i<80;i++)phase.update(12);
  const held={stage:phase.state.stage,age:phase.state.age,time:phase.state.time};
  for(let i=0;i<80;i++)phase.update(12);
  if(phase.state.stage!=='GIRL_APPROACH'||!phase.waitingForVisuals||phase.state.time!==held.time)throw Error('Introdução não reteve carregamento');
  if(phase.renderer?.room)throw Error('Mapa construído com atlas pendente');
  phase.render();return {...held,ready:phase.ready,introReady:phase.introReady,mapBuilt:Boolean(phase.renderer?.room)};
 })()`);console.log('CARREGAMENTO RETIDO',JSON.stringify(held));await save('abertura-aguardando');
 const loaded=await evaluate(`(async()=>{releaseAsset();await startPromise;Image.prototype.decode=originalDecode;if(!phase.ready||!phase.renderer?.ready)throw Error(phase.error||'3D não ficou pronto');if(phase.state.stage!=='GIRL_APPROACH')throw Error('Carregamento pulou a atuação obrigatória');for(let i=0;i<150&&phase.state.stage!=='CHASE_START';i++)phase.update(1);if(phase.state.stage!=='CHASE_START')throw Error('Não liberou a arrancada');for(let i=0;i<30;i++)phase.update(1);Object.assign(phase.state,{stage:'RUNNING',distance:39,gap:23,age:25,time:25});phase.render();const r=phase.renderer;let rgb=[0,0,0];for(const [x,y]of [[.3,.75],[.7,.75],[.4,.85],[.6,.85]]){const p=phase.ctx.getImageData(Math.floor(x*canvas.width),Math.floor(y*canvas.height),1,1).data;for(let i=0;i<3;i++)rgb[i]+=p[i]/4;}return {rgb,floorMode:r.floorMode,textures:[...r.resources].filter(t=>t.isTexture).length,error:r.renderer.getContext().getError()};})()`);
 assert.ok(loaded.rgb[0]>45&&loaded.rgb[0]>loaded.rgb[1]*1.1&&loaded.rgb[1]>loaded.rgb[2]*1.2,'Madeira visível: '+JSON.stringify(loaded));assert.equal(loaded.error,0);console.log('ARRANCADA PRONTA',JSON.stringify(loaded));await save('corrida-pronta');
 for(const [width,height]of [[390,844],[844,390]]) {
  await call('Emulation.setDeviceMetricsOverride',{width,height,deviceScaleFactor:1,mobile:true});
  const result=await evaluate(`(()=>{canvas.width=${width};canvas.height=${height};phase.render();let rgb=[0,0,0];for(const [x,y]of [[.3,.75],[.7,.75],[.4,.85],[.6,.85]]){const p=phase.ctx.getImageData(Math.floor(x*canvas.width),Math.floor(y*canvas.height),1,1).data;for(let i=0;i<3;i++)rgb[i]+=p[i]/4;}return {rgb,error:phase.renderer.renderer.getContext().getError()};})()`);
  assert.ok(result.rgb[0]>45&&result.rgb[0]>result.rgb[1]*1.1&&result.rgb[1]>result.rgb[2]*1.2,'Madeira em celular '+JSON.stringify(result));assert.equal(result.error,0);console.log('CELULAR',JSON.stringify({width,height,...result}));await save('corrida-'+width+'x'+height);
 }
 const fallback=await evaluate(`(async()=>{phase.destroy();const original=ChaseRenderer3D.prototype.floorIsVisible;let calls=0;ChaseRenderer3D.prototype.floorIsVisible=function(){return ++calls===1?false:original.call(this);};const r=new ChaseRenderer3D();try{await r.load();if(r.floorMode!=='linear'||!r.floorIsVisible())throw Error('Alternativa linear não confirmou madeira');return {mode:r.floorMode,calls,textures:[...r.resources].filter(t=>t.isTexture).length};}finally{ChaseRenderer3D.prototype.floorIsVisible=original;r.destroy();if(r.resources.size!==0)throw Error('Recursos não liberados');}})()`);console.log('RECUPERAÇÃO DO PISO',JSON.stringify(fallback));
 const failures=await evaluate(`(async()=>{const cases=[];for(const kind of ['piso','atlas']){const floor=ChaseRenderer3D.prototype.floorIsVisible,decode=Image.prototype.decode;let message=null;if(kind==='piso')ChaseRenderer3D.prototype.floorIsVisible=()=>false;else Image.prototype.decode=function(){return this.src.includes('urso-atlas-v2')?Promise.reject(Error('Atlas indisponível simulado')):decode.call(this);};const p=new BearChasePhase({canvas,audio:silent,enabled:()=>true,campaign:true,onCampaignError:m=>message=m});try{await p.start();if(p.ready||p.renderer||!p.error||!message)throw Error('Falha visual liberou corrida');const time=p.state.time;p.update(12);if(p.state.time!==time)throw Error('Falha visual avançou simulação');cases.push({kind,ready:p.ready,error:message});}finally{p.destroy();ChaseRenderer3D.prototype.floorIsVisible=floor;Image.prototype.decode=decode;}}return cases;})()`);console.log('FALHAS VISUAIS',JSON.stringify(failures));console.log('APROVADO: abertura obrigatória cobre carregamento, piso validado na GPU, alternativa linear e falhas impedem corrida.');
} finally {ws?.close();chrome.kill();await new Promise(r=>chrome.once('exit',r));await rm(profile,{recursive:true,force:true});}
